import json
from pathlib import Path
p=Path('content/isc2-cc-2026/sources/domain-5/production');out=Path('docs/plans/isc2-cc-2026')
r=json.loads(Path('artifacts/qa/domain5-production/independent-review.json').read_text(encoding='utf8')); ledger=json.loads((p/'qa-ledger.json').read_text(encoding='utf8'))
s='# Domain 5 question-level academic QA\n\nSeparate delegated assistant execution performed an English blind solve before opening keys; initial40/40 agreement with four-option judgments saved. This is actual execution independence, not ten human reviewers or native-Thai sign-off. Revision3 focused re-solves cover changed distractors;1032 mandatory rollback stem separately checked. Full evidence: `artifacts/qa/domain5-production/independent-review.json`; initial blind evidence: `blind-review-results.json`; runtime-hash-bound accepted records: `content/isc2-cc-2026/sources/domain-5/production/qa-ledger.json`.\n\n38 accepted,2 duplicate rejections. All ten0–5 dimensions>=4 and total>=45 (actualrange '+str(min(x['total50'] for x in ledger))+'–'+str(max(x['total50'] for x in ledger))+'/50). Original eight0–3 dimensions separately judged, every dimension>=2; totals do not override hard gates. Scores are editorial review aids, not difficulty calibration or empirical item-discrimination evidence.\n\n| ID | Ten-dimension total/50 | Original rubric/24 | Verdict | Evidence |\n|---|---|---|---|\n'
for x in r['items']:s+=f"| {x['id']} | {x['total50']} | {x['originalRubric0to3']['total24']} | {'REJECT duplicate' if x['id'] in [1003,1025] else 'ACCEPTED'} | Per-option solve, dimension reasoning, repair verification and comparators in item record |\n"
s+='\nRepairs:1003/1025 excluded for same assessed decisions as existing bank;1015 explicit alert purpose;1036 parallel test-method alternatives;1010 key-establishment Thai;1020 tactic terminology;1033/1039 removed asymmetric Thai answer glosses;13 option sets strengthened in revision3;1021 expressly irrelevant records;1032 mandatory rollback trigger; conservative cognitive/difficulty labels. R26–R28 strengthen direct encryption, collaboration and functional-exercise support.\n\nTechnical support was checked by author at claim level and a separate reviewer at targeted sources; reviewer did not independently reopen all81 original source files or every reference. The immutable earlier visual audit and matching source hashes supply provenance. Public official sample landing was retrievable but actual dynamic quiz wording was not: no sample-item style approval or confidential-item equivalence is claimed.\n'
(out/'domain-5-production-academic-qa.md').write_text(s,encoding='utf8')
manifest=json.loads((p/'authoring-manifest.json').read_text(encoding='utf8'))
for d in manifest:
 d['authoringStatus']=d['status'];d['status']='REJECTED' if d['id'] in [1003,1025] else 'ACCEPTED'
 if d['status']=='ACCEPTED':d['runtimeHash']=next(x['itemHash'] for x in ledger if x['id']==d['id'])
